import type { PatenteHistorico } from './Seccion7_6Patentes';

interface FilaAmpliacionGiro {
  numero: string;
  fecha: string;
  fechaPublicacion: string;
  tieneEfectosGenerales: 'Sí' | 'No';
  descripcion: string;
  ultimaActualizacion?: string;
  enlaceModificacion?: string;
  tipoNorma?: string;
  nombreTitulo?: string;
}

const crearRegistrosAmpliacionGiro = (
  filas: FilaAmpliacionGiro[],
  tipoNorma = 'Decretos Exentos'
): PatenteHistorico[] =>
  filas.map(({
    numero,
    fecha,
    fechaPublicacion,
    tieneEfectosGenerales,
    descripcion,
    ultimaActualizacion = 'Sin Modificaciones',
    enlaceModificacion = 'Sin Modificaciones',
    tipoNorma: tipoNormaFila,
    nombreTitulo = 'Ampliación de Giro'
  }) => ({
    tipoNorma: tipoNormaFila ?? tipoNorma,
    denominacion: 'Patentes y Permisos',
    nombreTitulo,
    numero,
    fecha,
    fechaPublicacion,
    tieneEfectosGenerales,
    ultimaActualizacion,
    descripcion,
    enlacePublicacion: 'PDF',
    enlaceModificacion,
    urlPublicacion: '',
    urlModificacion: ''
  }));

